import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Builds every pasted claim first, as the claim form would for its named person, so one refused
 *  line refuses the whole paste before anything is saved; then saves and audits each in order. */
public class AddPastedClaims {
    public void add(@PathVariable("sheetId") String sheetId, @Val PastedClaims paste, People people, Sheets sheets,
            ClosedPeriods closedPeriods, Claims claims, Settings settings, Holidays holidays, ClaimLog log, Audit audit,
            Out<PasteClaimsResult> result) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        List<Person> persons = new ArrayList<>();
        List<Claim> built = new ArrayList<>();
        for (PastedLine line : paste.lines()) {
            Person person = people.named(sheetId, line.name());
            if (person == null) throw new InvalidSheetRequestException("No one on the sheet is named " + line.name());
            persons.add(person);
            built.add(BuildClaim.built(line.values(), person, sheets, closedPeriods, claims, settings, holidays));
        }
        RecordClaimAdded record = new RecordClaimAdded();
        for (int i = 0; i < built.size(); i++) {
            claims.save(built.get(i));
            record.record(paste.lines().get(i).values(), persons.get(i), built.get(i), log, audit);
        }
        result.set(new PasteClaimsResult(built.size()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Gives the person an alias. The person is read afresh and locked, so two adds at once happen one
 *  after the other. Not an edit: the person's version is untouched. Refuses an alias equal, as names
 *  are compared, to any name or alias on the sheet. Publishes the person as they are now. */
public class AddAlias {
    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val AliasRequest request, People people, Out<Person> personOut, Out<Aliasing> aliasingOut)
            throws PersonNotFoundException, InvalidSheetRequestException {
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        String alias = request.alias().trim();
        if (people.nameOrAliasTaken(sheetId, alias)) {
            throw new InvalidSheetRequestException("The alias is already in use on this sheet");
        }
        people.addAlias(person, alias);
        personOut.set(person);
        aliasingOut.set(new Aliasing(person, alias, request.user()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A steward transfers the person to another sheet (see {@link Transfers#transfer}). Refused: anyone
 *  but a steward, a retired person, this sheet's own id, an archived sheet, and a name, alias or
 *  contact of the person already on the other sheet. Publishes the person as they arrived. */
public class TransferPerson {
    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val TransferRequest request, People people, Transfers transfers, Settings settings, Sheets sheets,
            Rollup rollup, Out<Person> personOut, Out<Transfer> transferOut)
            throws PersonNotFoundException, InvalidSheetRequestException {
        String to = request.to().trim();
        if (settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidSheetRequestException("A person cannot be transferred to their own sheet");
        }
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        if (person.isRetired()) {
            throw new InvalidSheetRequestException("A retired person cannot be transferred");
        }
        if (sheets.archived(to)) {
            throw new InvalidSheetRequestException("The other sheet is archived");
        }
        if (people.nameTaken(to, person.getName(), null)
                || person.getAliases().stream().anyMatch(alias -> people.nameOrAliasTaken(to, alias))
                || (person.getContact() != null && people.contactTaken(to, person.getContact(), null))) {
            throw new InvalidSheetRequestException("The other sheet already has this name, alias or contact");
        }
        Snapshot toBefore = rollup.snapshot(to);
        long arrivedId = transfers.transfer(person, to);
        personOut.set(people.find(to, arrivedId));
        transferOut.set(new Transfer(person.getName(), sheetId, to, request.user(), toBefore));
    }
}
