package net.officefloor.hq.app.sheet;

import java.sql.Connection;
import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A sheet as it stood at the end of a date: every change made while the sheet's today was on or
 *  before that date counts, every later change does not, and that date stands in for the sheet's
 *  today. The sheet's rows are rebuilt from the change history (see {@link History}) into the asof
 *  schema, and the work runs against it in place of the live tables, so every rule reads the sheet
 *  as it was. The work must only read: what it writes is thrown away. */
@Service
public class AsOf {

    /** The tables of a sheet's data (keyed by sheet_id) kept in asof_hist and rebuilt into asof. */
    static final List<String> TABLES = List.of("CLAIM", "PERSON", "PERSON_GRADE", "PERSON_HOLD", "PERSON_PATRON",
            "PERSON_WATCH", "PERSON_STATEMENT", "PERIOD", "PERIOD_PERSON_TOTAL", "PERIOD_NUMBER", "RATE",
            "SHEET_SETTING", "SHEET_SETTING_DATED", "SHEET_ROLE", "SHEET_PERMISSION", "SHEET_DELEGATION",
            "CLAIM_LOG", "SHEET_GRADE_TERMS", "SHEET_HOLIDAY", "SHEET_VOID_REASON", "CLAIM_COMMENT", "PERSON_ALIAS",
            "POOL", "POOL_MEMBER");

    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;
    private final Map<String, List<String>> columns = new HashMap<>();

    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager) {
        this.jdbc = jdbc;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    /** Run `work` against the sheet as it stood at the end of `date`. It runs in a transaction of its
     *  own, on one connection, which is rolled back: the rebuilt rows are never kept. */
    public <T> T at(String sheetId, LocalDate date, Supplier<T> work) {
        return transactions.execute(status -> {
            status.setRollbackOnly();
            // One rebuild of the sheet at a time.
            jdbc.query("SELECT id FROM PUBLIC.sheet WHERE id = ? FOR UPDATE", (RowCallbackHandler) rs -> {}, sheetId);
            rebuild(sheetId, date);
            schema("ASOF");
            try {
                return work.get();
            } finally {
                schema("PUBLIC");
            }
        });
    }

    /** What a screen reads: `work` on the sheet as it stood at the end of the as-of date given (see
     *  {@link #at}), or on the live sheet when none is given. Refused: an as-of that is not a date. */
    public <T> T view(String sheetId, String asOfText, Supplier<T> work) throws InvalidSheetRequestException {
        if (asOfText == null || asOfText.isBlank()) return work.get();
        LocalDate date;
        try {
            date = LocalDate.parse(asOfText.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + asOfText);
        }
        return at(sheetId, date, work);
    }

    private void rebuild(String sheetId, LocalDate date) {
        jdbc.update("DELETE FROM ASOF.sheet WHERE id = ?", sheetId);
        jdbc.update("INSERT INTO ASOF.sheet SELECT * FROM PUBLIC.sheet WHERE id = ?", sheetId);
        // Archived only by an archive made by then.
        jdbc.update("UPDATE ASOF.sheet SET today = ?, archived = archived AND (archived_on IS NULL OR archived_on <= ?) "
                + "WHERE id = ?", Date.valueOf(date), Date.valueOf(date), sheetId);
        for (String table : TABLES) {
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's aliases (sorted as names are compared, comma and space separated), and the entry and
 * button to add one. Aliases share the names' uniqueness: the server refuses a blank alias and one
 * equal, as names are compared, to any name or alias on the sheet.
 */
function PersonAliases({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [alias, setAlias] = useState('');
  const add = useMutation({
    mutationFn: (a: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/aliases`, { alias: a, user }),
    onSuccess: () => setAlias(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, add.reset);
  return (
    <>
      <td data-testid="person-aliases">{person.aliases.join(', ')}</td>
      <td>
        <input
          type="text"
          placeholder="alias"
          data-testid="person-alias-input"
          value={alias}
          onChange={(e) => {
            setAlias(e.target.value);
            add.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-alias-add"
          disabled={add.isPending}
          onClick={() => {
            actionTaken();
            add.reset();
            add.mutate(alias);
          }}
        >
          Add alias
        </button>
        {add.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not add this alias (not blank, and not a name or alias already on the sheet).
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 5,
    Component: () => (
      <>
        <th>Aliases</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 5, Component: PersonAliases }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
